<script setup>
import { computed } from 'vue'; import { Bar, Line } from 'vue-chartjs'; import { Chart as ChartJS, Title, Tooltip, Legend, BarElement, CategoryScale, LinearScale, PointElement, LineElement } from 'chart.js'; import StatCard from '../components/StatCard.vue'; import { getOverallStats, getCategoryStats, getAccuracyTrend, getWeakestOncologyTopics, getStrongestOncologyTopics } from '../utils/statistics'
ChartJS.register(Title, Tooltip, Legend, BarElement, CategoryScale, LinearScale, PointElement, LineElement)
const overall=computed(getOverallStats); const cats=computed(()=>['SIMAK UI','LPDP','Onkologi Radiasi'].map(getCategoryStats)); const trend=computed(getAccuracyTrend)
const lineData=computed(()=>({labels:trend.value.map(x=>x.date),datasets:[{label:'Akurasi harian',data:trend.value.map(x=>x.accuracy),borderColor:'#2563eb',backgroundColor:'#93c5fd'}]})); const barData=computed(()=>({labels:cats.value.map(x=>x.category),datasets:[{label:'Akurasi kategori',data:cats.value.map(x=>x.accuracy),backgroundColor:['#1d4ed8','#7c3aed','#0f766e']}]}))
</script>
<template><section class="page"><h1>Statistik</h1><div class="stat-grid"><StatCard title="Total soal dikerjakan" :value="overall.totalAnswered"/><StatCard title="Total sesi" :value="overall.totalSessions"/><StatCard title="Total hari belajar" :value="overall.totalDays"/><StatCard title="Streak" :value="`${overall.streak} hari`"/><StatCard title="Akurasi keseluruhan" :value="`${overall.accuracy}%`"/></div><div class="chart-grid"><div class="card"><h2>Grafik progress harian</h2><Line :data="lineData" /></div><div class="card"><h2>Akurasi per kategori</h2><Bar :data="barData" /></div></div><div class="grid-two"><div class="card"><h2>Topik Onkologi terlemah</h2><ul><li v-for="t in getWeakestOncologyTopics()" :key="t.topic">{{ t.topic }} — {{ t.accuracy }}%</li></ul></div><div class="card"><h2>Topik Onkologi terkuat</h2><ul><li v-for="t in getStrongestOncologyTopics()" :key="t.topic">{{ t.topic }} — {{ t.accuracy }}%</li></ul></div></div></section></template>
